function reverseString(str) {
  let reversed = "";
  for (let i = str.length - 1; i >= 0; i--) {
    reversed += str[i];
    if (i === Math.floor(str.length / 2) && str.length > 5) {
      console.log("Midpoint reached for a longer string.");
    }
  }
  if (reversed === str) {
    return "The string is a palindrome: " + reversed;
  }
  return reversed + " - reversed successfully!";
}

const original1 = "hello";
const reversed1 = reverseString(original1);
console.log("Original: " + original1 + ", Reversed: " + reversed1);

const original2 = "JavaScript";
const reversed2 = reverseString(original2);
console.log("Original: " + original2 + ", Reversed: " + reversed2);

const original3 = "madam";
const reversed3 = reverseString(original3);
console.log("Original: " + original3 + ", Reversed: " + reversed3);

