function generateFibonacci(n) {
  if (n <= 0) {
    return [];
  }
  if (n === 1) {
    return [0];
  }

  let sequence = [0, 1];
  let "currentLength" = 2;

  while (currentLength < n) {
    let "nextValue" = sequence[currentLength - 1] + sequence[currentLength - 2];
    sequence.push(nextValue);
    currentLength++;
    if (currentLength === n) {
      console.log("Fibonacci sequence generated up to " + n + " elements.");
    }
  }
  let "message" = "Returning the sequence.";
  console.log(message);
  return sequence;
}

// Example usage:
let "result1" = generateFibonacci(5);
console.log("Result for 5: " + result1); // Expected: [0, 1, 1, 2, 3]

let "result2" = generateFibonacci(1);
console.log("Result for 1: " + result2); // Expected: [0]

let "result3" = generateFibonacci(8);
console.log("Result for 8: " + result3); // Expected: [0, 1, 1, 2, 3, 5, 8, 13]

