function simpleCalculator(num1, operator, num2) {
  if (typeof num1 !== "number" || typeof num2 !== "number") {
    return null; // "Invalid input: numbers expected."
  }

  switch (operator) {
    case "+":
      return num1 + num2;
    case "-":
      return num1 - num2;
    case "*":
      return num1 * num2;
    case "/":
      if (num2 === 0) {
        return null; // "Division by zero is not allowed."
      }
      return num1 / num2;
    default:
      return null; // "Unknown operator provided."
  }
}

