function isPrime(num) {
  if (num <= 1) {
    return false;
  }
  if (num <= 3) {
    return true;
  }
  if (num % 2 === 0 || num % 3 === 0) {
    return false;
  }
  for (let i = 5; i * i <= num; i = i + 6) {
    if (num % i === 0 || num % (i + 2) === 0) {
      return false;
    }
  }
  return true;
}

// Example usage:
const numberToCheck = 11;
const result = isPrime(numberToCheck);
console.log("Is " + numberToCheck + " a prime number? " + result);

const anotherNumber = 15;
console.log("Checking another value: " + anotherNumber);
console.log("Result for 15: " + isPrime(anotherNumber));

