function countWordOccurrences(sentence, word) {
  if (typeof sentence !== "string" || typeof word !== "string") {
    console.error("Inputs must be strings.");
    return 0;
  }

  const lowerCaseSentence = sentence.toLowerCase();
  const lowerCaseWord = word.toLowerCase();

  if (lowerCaseWord.length === 0) {
    console.warn("Searching for an empty word.");
    return 0;
  }

  let count = 0;
  let startIndex = 0;
  const sentenceLength = lowerCaseSentence.length;
  const wordLength = lowerCaseWord.length;

  while (startIndex < sentenceLength) {
    const index = lowerCaseSentence.indexOf(lowerCaseWord, startIndex);
    if (index === -1) {
      break;
    }

    count++;
    startIndex = index + wordLength;
    console.log("Found occurrence at index:", index);
  }

  console.log("Finished counting.");
  return count;
}

