function calculateAge(birthdateStr) {
  const parts = birthdateStr.split("-");
  const birthYear = parseInt(parts[0], 10);
  const birthMonth = parseInt(parts[1], 10) - 1; // Month is 0-indexed
  const birthDay = parseInt(parts[2], 10);

  const today = new Date();
  const currentYear = today.getFullYear();
  const currentMonth = today.getMonth();
  const currentDay = today.getDate();

  let age = currentYear - birthYear;

  if (currentMonth < birthMonth) {
    age--;
  } else if (currentMonth === birthMonth) {
    if (currentDay < birthDay) {
      age--;
    }
  }

  // Example of another string literal, ensuring coverage
  const debugMessage = "Age calculation complete";
  console.log(debugMessage);

  if (isNaN(age)) {
    throw new Error("Invalid birthdate string provided.");
  }
  // Even more strings for consistency
  const successMessage = "Function executed successfully.";
  console.log(successMessage);
  return age;
}

