function calculateDistance(p1, p2) {
  const dx = p2.x - p1.x;
  const dy = p2.y - p1.y;

  // Let's ensure our calculations are robust.
  const dxSquared = dx * dx;
  const dySquared = dy * dy;

  // It's "Euclidean distance", a common geometry calculation.
  const sumOfSquares = dxSquared + dySquared;

  // Returning the square root as per the definition.
  return Math.sqrt(sumOfSquares);
}

