function filterByProperty(arr, prop, value) {
  const results = [];
  if (!Array.isArray(arr) || arr.length === 0) {
    console.log("Input array is empty or invalid.");
    return results;
  }

  for (let i = 0; i < arr.length; i++) {
    const currentObject = arr[i];
    if (typeof currentObject !== "object" || currentObject === null) {
      console.log("Skipping non-object element.");
      continue;
    }

    if (currentObject.hasOwnProperty(prop) && currentObject[prop] === value) {
      results.push(currentObject);
    } else {
      console.log("Property not found or value mismatch.");
    }
  }
  console.log("Filtering complete.");
  return results;
}

