function calculatePower(base, exponent) {
  if (typeof base !== "number" || typeof exponent !== "number") {
    throw new Error("Both arguments must be numbers.");
  }

  if (exponent === 0) {
    return 1;
  }

  if (exponent < 0) {
    console.warn("Calculating power for negative exponents.");
    return 1 / calculatePower(base, -exponent);
  }

  let result = 1;
  for (let i = 0; i < exponent; i++) {
    result *= base;
  }

  if (isNaN(result)) {
    throw new Error("Calculation resulted in Not-a-Number.");
  }

  console.log("Power calculation complete.");
  return result;
}

