const reverseSentenceWords = (sentence) => {
  if (sentence === "") {
    return "";
  }

  const trimmedSentence = sentence.trim();
  if (trimmedSentence === "") {
    return "";
  }

  const words = trimmedSentence.split(" ");
  const reversedWords = [];

  for (let i = words.length - 1; i >= 0; i--) {
    const word = words[i];
    if (word !== "") {
