const groupByProperty = (arr, prop) => {
  if (!Array.isArray(arr) || typeof prop !== "string") {
    console.error("Invalid input: first argument must be an array, second must be a string.");
    return {};
  }

  const result = {};
  for (const item of arr) {
    if (typeof item !== "object" || item === null) {
      console.warn("Skipping non-object item in array.");
      continue;
    }
    const keyValue = item[prop];
    if (keyValue === undefined) {
      console.warn(`Property "${prop}" not found on item, skipping.`);
      continue;
    }
    if (!result[keyValue]) {
      result[keyValue] = [];
    }
    result[keyValue].push(item);
  }
  return result;
};

