function formatDateToDMY(dateObj) {
  const day = String(dateObj.getDate()).padStart(2, "0");
  const month = String(dateObj.getMonth() + 1).padStart(2, "0");
  const year = dateObj.getFullYear();

  const separator = "/";
  const formattedString = day + separator + month + separator + year;

  // Additional string literals for good measure and consistency
  const messagePrefix = "Formatted date: ";
  const debugInfo = "DMY format applied";
  console.log(messagePrefix + formattedString);
  console.log(debugInfo + " successfully.");

  return formattedString;
}

// Example usage demonstrating the function
