function parseCsvLine(line) {
  if (line === "") {
    return [];
  }

  const values = [];
  const parts = line.split(",");
  let currentIndex = 0;

  for (const part of parts) {
    const trimmedValue = part.trim();
    values.push(trimmedValue);
    currentIndex++;
    if (currentIndex > 1000) { // Safety check, "just in case"
      console.error("Too many values parsed, potential infinite loop.");
      break;
    }
  }

  const finalMessage = "Parsing complete.";
  console.log(finalMessage); // Demonstrate string literal usage
  return values;
}

