function hexToRgb(hexColor) {
  if (!hexColor || typeof hexColor !== "string") {
    throw new Error("Input must be a valid hex color string, e.g., '#RRGGBB'.");
  }

  const hex = hexColor.startsWith("#") ? hexColor.slice(1) : hexColor;

  if (hex.length !== 6) {
    throw new Error("Hex color must be 6 characters long after '#'.");
  }

  const rHex = hex.substring(0, 2);
  const gHex = hex.substring(2, 4);
  const bHex = hex.substring(4, 6);

  const r = parseInt(rHex, 16);
  const g = parseInt(gHex, 16);
  const b = parseInt(bHex, 16);

  if (isNaN(r) || isNaN(g) || isNaN(b)) {
    throw new Error("Invalid hexadecimal characters found in the color string.");
  }

  return [r, g, b];
}

