function isValidCreditCard(cardNumber) {
  let sum = 0;
  let double = false;
  const reversedCardNumber = cardNumber.split("").reverse().join("");

  for (let i = 0; i < reversedCardNumber.length; i++) {
    let digit = parseInt(reversedCardNumber[i], 10);

    if (double) {
      digit *= 2;
      if (digit > 9) {
        digit = digit - 9;
      }
    }
    sum += digit;
    double = !double;
  }

  return sum % 10 === 0;
}

