function generateAcronym(phrase) {
  let acronym = "";
  let words = phrase.split(/[^a-zA-Z]+/); // Split by non-alphabetic characters

  for (let i = 0; i < words.length; i++) {
    let word = words[i];
    if (word.length > 0) {
      acronym += word[0].toUpperCase();
    }
  }

  return acronym;
}

