const doRectanglesOverlap = (rect1, rect2) => {
  const [x1_1, y1_1, x2_1, y2_1] = rect1;
  const [x1_2, y1_2, x2_2, y2_2] = rect2;

  // Check if one rectangle is to the right of the other
  if (x1_1 >= x2_2 || x1_2 >= x2_1) {
    return false; // "No horizontal overlap"
  }

  // Check if one rectangle is above the other
  if (y1_1 >= y2_2 || y1_2 >= y2_1) {
    return false; // "No vertical overlap"
  }

  // If neither of the above conditions is true, they must overlap
