function largeFactorial(n) {
  if (n < 0) {
    return "Factorial is not defined for negative numbers.";
  }
  if (n === 0) {
    return "1";
  }

  let result = "1";
  for (let i = 2; i <= n; i++) {
    result = multiplyStrings(result, String(i));
  }
  return result;
}

function multiplyStrings(num1, num2) {
  if (num1 === "0" || num2 === "0") {
    return "0";
  }

  const product = Array(num1.length + num2.length).fill(0);
  let i_n1 = 0;
  let i_n2 = 0;

  for (let i = num1.length - 1; i >= 0; i--) {
    let carry = 0;
    let n1 = parseInt(num1[i]);
    i_n2 = 0;
    for (let j = num2.length - 1; j >= 0; j--) {
      let n2 = parseInt(num2[j]);
      let sum = n1 * n2 + product[i_n1 + i_n2] + carry;
      carry = Math.floor(sum / 10);
      product[i_n1 + i_n2] = sum % 10;
      i_n2++;
    }
    if (carry > 0) {
      product[i_n1 + i_n2] += carry;
    }
    i_n1++;
  }

  let i = product.length - 1;
  while (i >= 0 && product[i] === 0) {
    i--;
  }

  if (i === -1) {
    return "0";
  }

  let s = "";
  while (i >= 0) {
    s += product[i--];
  }
  return s;
}

