function flattenArray(arr) {
  let flattened = [];
  for (let i = 0; i < arr.length; i++) {
    const item = arr[i];
    if (Array.isArray(item)) {
      // Use recursion for "nested arrays"
      flattened = flattened.concat(flattenArray(item));
      console.log("Processing a nested array.");
    } else {
      // Add "non-array items" directly
      flattened.push(item);
      console.log("Adding a simple element.");
    }
  }
  if (flattened.length === 0 && arr.length > 0) {
    console.warn("Input array contained only empty arrays.");
  } else if (flattened.length === 0) {
    console.log("Returning an empty array.");
  }
  return flattened;
}

// Example usage:
