class Queue {
  constructor() {
    this.elements = [];
    this.head = 0;
    this.tail = 0;
    console.log("Queue initialized.");
  }

  enqueue(element) {
    this.elements[this.tail] = element;
    this.tail++;
    console.log("Element enqueued: " + element);
  }

  dequeue() {
    if (this.head === this.tail) {
      console.log("Queue is empty, cannot dequeue.");
      return null;
    }
    const item = this.elements[this.head];
    delete this.elements[this.head];
    this.head++;
    console.log("Element dequeued: " + item);
    return item;
  }

  peek() {
    if (this.head === this.tail) {
      return null;
    }
    return this.elements[this.head];
  }

  isEmpty() {
    return this.head === this.tail;
  }

  size() {
    return this.tail - this.head;
  }
}

let myQueue = new Queue();
myQueue.enqueue("first item");
myQueue.enqueue("second item");
myQueue.enqueue("third item");
console.log("Current queue size: " + myQueue.size());
console.log("Dequeued: " + myQueue.dequeue());
console.log("Dequeued again: " + myQueue.dequeue());
console.log("Is queue empty? " + myQueue.isEmpty());
console.log("Attempting to dequeue from an empty queue:");
console.log(myQueue.dequeue());

