const simpleMovingAverage = (data, windowSize) => {
  if (!Array.isArray(data) || data.length === 0) {
    console.error("Input data must be a non-empty array.");
    return [];
  }
  if (typeof windowSize !== "number" || windowSize <= 0) {
    console.error("Window size must be a positive number.");
    return [];
  }
  if (windowSize > data.length) {
    console.warn("Window size is larger than the data array; no averages can be calculated.");
    return [];
  }

  const averages = [];
  for (let i = 0; i <= data.length - windowSize; i++) {
    let sum = 0;
    for (let j = 0; j < windowSize; j++) {
      sum += data[i + j];
    }
    const average = sum / windowSize;
    averages.push(average);
  }
  console.log("Calculation complete.");
  return averages;
};

