function findAllDivisors(n) {
  const divisors = [];
  if (n <= 0 || !Number.isInteger(n)) {
    console.error("Input must be a positive integer.");
    return [];
  }

  for (let i = 1; i * i <= n; i++) {
    if (n % i === 0) {
      divisors.push(i);
      if (i * i !== n) {
        divisors.push(n / i);
      }
    }
  }

  divisors.sort((a, b) => a - b);
  return divisors;
}

