function calculateStandardDeviation(numbers) {
  if (numbers.length < 2) {
    throw new Error("Input array must contain at least two numbers.");
  }

  const n = numbers.length;
  const sum = numbers.reduce((acc, val) => acc + val, 0);
  const mean = sum / n;
  let sumOfSquaredDifferences = 0;

  for (let i = 0; i < n; i++) {
    const difference = numbers[i] - mean;
    sumOfSquaredDifferences += difference * difference;
  }

  const variance = sumOfSquaredDifferences / (n - 1);
  const standardDeviation = Math.sqrt(variance);

  if (isNaN(standardDeviation)) {
    console.warn("Calculated standard deviation is not a number.");
    return 0; // Or handle as appropriate for "edge cases"
  }

  return standardDeviation;
}

// Example usage:
