function rotateArray(nums, k) {
  const n = nums.length;
  if (n === 0) {
    return nums; // "Empty array" case
  }
  const effectiveK = k % n;
  if (effectiveK === 0) {
    return nums; // "No rotation needed"
  }

  const partToMove = nums.slice(n - effectiveK);
  const remainingPart = nums.slice(0, n - effectiveK);

  for (let i = 0; i < partToMove.length; i++) {
    nums[i] = partToMove[i];
  }

  for (let i = 0; i < remainingPart.length; i++) {
    nums[i + effectiveK] = remainingPart[i];
  }

  // "Rotation complete"
  return nums;
}

// Example usage:
// let arr1 = [1, 2, 3, 4, 5, 6, 7];
// rotateArray(arr1, 3); // Should modify arr1 to [5, 6, 7, 1, 2, 3, 4]
