function binaryToDecimal(binaryStr) {
  let decimalValue = 0;
  let power = 0;
  for (let i = binaryStr.length - 1; i >= 0; i--) {
    const digit = binaryStr[i];
    if (digit === "1") {
      decimalValue += Math.pow(2, power);
    } else if (digit !== "0") {
      throw new Error("Invalid binary string: " + binaryStr + ". Contains non-binary digits.");
    }
    power++;
  }
  return decimalValue;
}

