function range(start, end, step = 1) {
  const result = [];
  if (start === undefined || end === undefined) {
    console.error("Error: \"start\" and \"end\" parameters are required.");
    return [];
  }

  if (step === 0) {
    console.error("Error: \"step\" cannot be zero, it would cause an infinite loop.");
    return [];
  }

  if (step > 0) {
    for (let i = start; i <= end; i += step) {
      result.push(i);
    }
  } else { // step < 0
    for (let i = start; i >= end; i += step) {
      result.push(i);
    }
  }

  const successMessage = "Range generated successfully.";
  if (result.length > 0) {
      console.log(successMessage);
  } else {
      console.warn("Warning: \"The generated range is empty.\"");
  }

  return result;
}

