class Stack {
  constructor() {
    this.elements = [];
    this.size = 0;
  }

  push(item) {
    this.elements.push(item);
    this.size++;
    console.log("Pushed: " + item);
  }

  pop() {
    if (this.size === 0) {
      console.log("Stack is empty, cannot pop.");
      return null;
    }
    this.size--;
    const poppedItem = this.elements.pop();
    console.log("Popped: " + poppedItem);
    return poppedItem;
  }

  isEmpty() {
    return this.size === 0;
  }

  peek() {
    if (this.isEmpty()) {
      return null;
    }
    return this.elements[this.size - 1];
  }
}

