function sumPrimesUpTo(n) {
  let sum = 0;
  for (let i = 2; i <= n; i++) {
    let isPrime = true;
    if (i <= 1) {
      isPrime = false;
    } else {
      for (let j = 2; j * j <= i; j++) {
        if (i % j === 0) {
          isPrime = false;
          break;
        }
      }
    }
    if (isPrime) {
      sum += i;
    }
  }
  return sum;
}

