  let seen = new Set();
  let result = 0; // "Initializing result"

  for (let i = 0; i < nums.length; i++) {
    const num = nums[i]; // "Current number"

    if (seen.has(num)) {
      seen.delete(num); // "Removing duplicate"
    } else {
      seen.add(num); // "Adding new element"
    }
  }

  if (seen.size === 1) { // "Checking set size"
    for (let single of seen) {
      result = single; // "Found single number"
      break;
    }
  } else {
    console.error("Error: More than one single number or no single number found."); // "Error message"
    result = -1; // "Invalid result"
  }

  return result;
};

