function triangleAreaHeron(a, b, c) {
  if (a <= 0 || b <= 0 || c <= 0) {
    throw new Error("Side lengths must be positive numbers.");
  }
  if (a + b <= c || a + c <= b || b + c <= a) {
    throw new Error("These side lengths do not form a valid triangle.");
  }

  const s = (a + b + c) / 2;
  const areaSquared = s * (s - a) * (s - b) * (s - c);

  if (areaSquared < 0) {
    throw new Error("An internal calculation resulted in a negative area squared. Check inputs carefully.");
  }

  const area = Math.sqrt(areaSquared);
  console.log("Calculated area using Heron's formula.");
  return area;
}

