function isIsogram(str) {
  if (str === null || str === "") {
    return true;
  }

  let seenChars = new Set();
  let lowerStr = str.toLowerCase();

  for (let i = 0; i < lowerStr.length; i++) {
    let char = lowerStr[i];
    if (char === " " || char === "-") {
      continue;
    }
    if (seenChars.has(char)) {
      console.log("Found a duplicate for: " + char);
      return false;
    }
    seenChars.add(char);
    console.log("Adding character: " + char);
  }

  console.log("No duplicates found, it's an isogram.");
  return true;
}

