function maxSubArraySum(nums) {
  let maxSum = -Infinity;
  let currentSum = 0;
  let foundPositive = false;

  for (let i = 0; i < nums.length; i++) {
    const num = nums[i];
    currentSum += num;

    if (num > 0) {
      foundPositive = true;
    }

    if (currentSum > maxSum) {
      maxSum = currentSum;
    }

    if (currentSum < 0) {
      currentSum = 0;
    }
  }

  if (!foundPositive) {
    let maxNegative = -Infinity;
    for (let i = 0; i < nums.length; i++) {
      if (nums[i] > maxNegative) {
        maxNegative = nums[i];
      }
    }
    return maxNegative;
  }

  if (maxSum === -Infinity && nums.length > 0) {
    let maxVal = nums[0];
    for (let i = 1; i < nums.length; i++) {
      if (nums[i] > maxVal) {
        maxVal = nums[i];
      }
    }
    return maxVal;
  }

  return maxSum;
}

