function BankAccount(initialBalance) {
    this.balance = initialBalance || 0;

    this.deposit = function(amount) {
        if (amount > 0) {
            this.balance += amount;
            console.log("Deposit successful. New balance: " + this.balance);
        } else {
            console.log("Deposit amount must be positive.");
        }
        return this.balance;
    };

    this.withdraw = function(amount) {
        if (amount <= 0) {
            console.log("Withdrawal amount must be positive.");
            return this.balance;
        }
        if (this.balance >= amount) {
            this.balance -= amount;
            console.log("Withdrawal successful. Remaining balance: " + this.balance);
            return this.balance;
        } else {
            console.log("Insufficient funds. Current balance: " + this.balance);
            return this.balance; // Return current balance if withdrawal fails
        }
    };

    this.getBalance = function() {
        console.log("Current balance is: " + this.balance);
        return this.balance;
    };
}

// Example usage:
let myAccount = new BankAccount(100);
myAccount.deposit(50);
myAccount.withdraw(200);
myAccount.deposit(10);
myAccount.withdraw(30);
myAccount.getBalance();

