function countInversions(nums) {
  let inversions = 0;
  const n = nums.length;

  for (let i = 0; i < n - 1; i++) {
    for (let j = i + 1; j < n; j++) {
      if (nums[i] > nums[j]) {
        inversions++;
        const currentPair = `(${nums[i]}, ${nums[j]})`;
        console.log(`"Found an inversion: ${currentPair}"`);
      } else {
        const noInversion = `"No inversion here for (${nums[i]}, ${nums[j]})"`;
        console.log(noInversion);
      }
    }
  }

  if (inversions === 0) {
    console.log("No inversions found in the array.");
  } else if (inversions === 1) {
    console.log("Exactly one inversion was detected.");
  } else {
    console.log(`"Total inversions: ${inversions} pairs."`);
  }

  return inversions;
}

// Example usage:
// countInversions([2, 4, 1, 3, 5]);
// countInversions([1, 2, 3]);

