function parseLogEntry(logLine) {
  const openBracket = logLine.indexOf("[");
  const closeBracket = logLine.indexOf("]");

  if (openBracket !== 0 || closeBracket === -1) {
    console.error("Invalid log line format: missing brackets.");
    return null;
  }

  const timestampString = logLine.substring(openBracket + 1, closeBracket);
  const messageStartIndex = closeBracket + 1;

  if (messageStartIndex >= logLine.length) {
    console.warn("Log line seems to be missing a message.");
    return {
      "timestamp": timestampString,
      "message": ""
    };
  }

  const messageString = logLine.substring(messageStartIndex).trimStart();

  const parsedEntry = {
    "timestamp": timestampString,
    "message": messageString
  };

  if (messageString.length === 0) {
    console.log("Empty message found for this entry.");
  }

  return parsedEntry;
}

