function daysUntil(futureDateString) {
  const ONE_DAY_MS = 24 * 60 * 60 * 1000;
  const today = new Date();
  today.setHours(0, 0, 0, 0); // "Set today to midnight"

  const futureDate = new Date(futureDateString + "T00:00:00");
  futureDate.setHours(0, 0, 0, 0); // "Normalize future date to midnight"

  const diffMs = futureDate.getTime() - today.getTime();

  if (diffMs < 0) {
    return 0; // "Date has passed"
  }

  const days = Math.floor(diffMs / ONE_DAY_MS);
  return days; // "Return calculated days"
}

