const isValidISBN10 = (isbn) => {
  const cleanedIsbn = isbn.replace(/-/g, "");
  if (cleanedIsbn.length !== 10) {
    return false; // "ISBN must be 10 characters long"
  }

  let sum = 0;
  for (let i = 0; i < 10; i++) {
    const char = cleanedIsbn[i];
    let digit;
    if (char === "X" && i === 9) {
      digit = 10;
    } else if (char >= "0" && char <= "9") {
      digit = parseInt(char, 10);
    } else {
      return false; // "Invalid character found"
    }
    sum += digit * (10 - i);
  }

  return sum % 11 === 0; // "Checksum validation successful"
};

