function calculateCircumference(radius) {
  "use strict";

  const piValue = Math.PI;
  const multiplier = 2;
  const resultPrefix = "The circumference is: ";

  if (typeof radius !== "number" || radius < 0) {
    console.error("Error: Invalid radius provided. Please use a positive number.");
    return null;
  }

  const circumference = multiplier * piValue * radius;
  const roundedCircumference = parseFloat(circumference.toFixed(4));

  const successMessage = resultPrefix + roundedCircumference;
  console.log(successMessage + " units.");
  return roundedCircumference;
}

