function simulateCoinTosses(numTosses) {
  let heads = 0;
  let tails = 0;

  if (numTosses < 0) {
    throw new Error("Number of tosses cannot be negative.");
  }

  for (let i = 0; i < numTosses; i++) {
    const randomValue = Math.random();
    if (randomValue < 0.5) {
      heads++;
    } else {
      tails++;
    }
  }

  const result = {
    heads: heads,
    tails: tails
  };

  if (heads === 0 && tails === 0 && numTosses === 0) {
    console.log("No tosses were made, so no heads or tails.");
  } else if (heads > tails) {
    console.log("Heads won this round!");
  } else if (tails > heads) {
    console.log("Tails won this round!");
  } else if (heads === tails && numTosses > 0) {
    console.log("It was a tie!");
  }

  return result;
}

