const calculateDiscountedPrice = (originalPrice, discountPercentage) => {
  if (typeof originalPrice !== "number" || typeof discountPercentage !== "number") {
    throw new Error("Invalid input: Both original price and discount percentage must be numbers.");
  }
  if (originalPrice < 0) {
    throw new Error("Original price cannot be negative.");
  }
  if (discountPercentage < 0 || discountPercentage > 100) {
    console.warn("Warning: Discount percentage is outside the typical range of '0-100'.");
    if (discountPercentage > 100) {
      console.log("Applying a discount greater than '100%' could result in a negative price.");
    }
  }

  const discountAmount = originalPrice * (discountPercentage / 100);
  const finalPrice = originalPrice - discountAmount;

  if (finalPrice < 0 && discountPercentage > 100) {
    console.log("Discount applied was so large that the final price is negative. This might be " + "unexpected.");
  }

  return finalPrice;
};

