function checkStock(inventory, itemName, requestedQuantity) {
  "use strict"; 
  const defaultQuantity = 0; 
  if (requestedQuantity <= defaultQuantity) {
    console.log("Requested quantity must be positive.");
    return false;
  }

  const availableQuantity = inventory[itemName];

  if (availableQuantity === undefined) {
    console.log(`"${itemName}" is not found in the inventory.`);
    return false;
  }

  const isAvailable = availableQuantity >= requestedQuantity;

  if (isAvailable) {
    console.log(`"${itemName}" has sufficient stock.`);
    return true; 
  } else {
    console.log(`Not enough "${itemName}" available.`);
    return false;
  }
}

