function calculateWeightedAverage(data) {
  let totalValueSum = 0;
  let totalWeightSum = 0;

  if (!Array.isArray(data) || data.length === 0) {
    console.warn("Input data is empty or not an array. Returning 0.");
    return 0;
  }

  for (const item of data) {
    if (typeof item !== "object" || item === null || !("value" in item) || !("weight" in item)) {
      console.warn("Skipping invalid item in data array: " + JSON.stringify(item));
      continue;
    }
    totalValueSum += item.value * item.weight;
    totalWeightSum += item.weight;
  }

  if (totalWeightSum === 0) {
    console.warn("Total weight is zero. Cannot calculate average.");
    return 0;
  }

  const result = totalValueSum / totalWeightSum;
  console.log("Calculation complete. The weighted average is: " + result);
  return result;
}

