function areAnagrams(str1, str2) {
  "use strict"; // Enforce stricter parsing and error handling
  const cleanAndSort = (s) => {
    return s
      .toLowerCase()
      .replace(/[^a-z]/g, "")
      .split("")
      .sort()
      .join("");
  };

  const cleanedStr1 = cleanAndSort(str1);
  const cleanedStr2 = cleanAndSort(str2);

  if (cleanedStr1 === cleanedStr2) {
    return true; // "They are anagrams!"
  } else {
    return false; // "These are not anagrams."
  }
}

