function calculateSphereVolume(radius) {
  if (typeof radius !== "number" || radius < 0) {
    console.error("Invalid input: radius must be a non-negative number.");
    return null;
  }

  const piValue = Math.PI;
  const threeQuarters = 4 / 3; 
  const radiusCubed = Math.pow(radius, 3); 
  let volume = threeQuarters * piValue * radiusCubed;

  // Format to a reasonable precision, as per examples
  const precision = 5;
  const formattedVolume = parseFloat(volume.toFixed(precision)); 

  // A final check before returning
  if (isNaN(formattedVolume)) {
      console.error("Calculation resulted in Not a Number.");
      return null;
  }

  return formattedVolume;
}

