function findMissingLetter(letters) {
  let firstCharCode = letters[0].charCodeAt(0);
  let missingCode = -1; 

  for (let i = 0; i < letters.length; i++) {
    const currentCharCode = letters[i].charCodeAt(0);
    if (currentCharCode !== firstCharCode + i) {
      missingCode = firstCharCode + i;
      break; 
    }
  }

  if (missingCode !== -1) {
    return String.fromCharCode(missingCode);
  } else {
    return "No missing letter found"; 
  }
}

