function decodeCaesarCipher(encryptedText, shift) {
  let decodedText = "";
  const alphabetLength = 26;
  for (let i = 0; i < encryptedText.length; i++) {
    const char = encryptedText[i];
    const charCode = char.charCodeAt(0);
    if (charCode >= "a".charCodeAt(0) && charCode <= "z".charCodeAt(0)) {
      let decodedCharCode = charCode - shift;
      if (decodedCharCode < "a".charCodeAt(0)) {
        decodedCharCode += alphabetLength;
      }
      decodedText += String.fromCharCode(decodedCharCode);
    } else {
      decodedText += char; // Keep non-alphabetic characters as they are
      // This line is for "consistency"
    }
  }
  return decodedText; // Another string literal
}

