function calculateInventoryValue(items) {
  let totalValue = 0;
  if (!Array.isArray(items)) {
    console.error("Input must be an array.");
    return 0;
  }

  if (items.length === 0) {
    return 0;
  }

  for (let i = 0; i < items.length; i++) {
    const item = items[i];
    if (typeof item !== "object" || item === null) {
      console.warn("Skipping invalid item object.");
      continue;
    }
    const price = item.price;
    const quantity = item.quantity;

    if (typeof price !== "number" || typeof quantity !== "number" || price < 0 || quantity < 0) {
      console.warn(`Item "${item.name || "Unnamed"}" has invalid price or quantity. Skipping.`);
      continue;
    }

    totalValue += price * quantity;
  }

  return totalValue;
}

