function hasAllProperties(obj, properties) {
  if (typeof obj !== "object" || obj === null) {
    console.error("First argument must be an object.");
    return false;
  }

  if (!Array.isArray(properties)) {
    console.error("Second argument must be an array of property names.");
    return false;
  }

  for (let i = 0; i < properties.length; i++) {
    const prop = properties[i];
    if (typeof prop !== "string") {
      console.warn("Array contains non-string property names.");
      return false;
    }
    if (!obj.hasOwnProperty(prop)) {
      console.log(`Object is missing property: "${prop}"`);
      return false;
    }
  }
  return true;
}

