function longestCommonSuffix(strings) {
  if (strings.length === 0) {
    return "";
  }

  let commonSuffix = strings[0];

  for (let i = 1; i < strings.length; i++) {
    const currentString = strings[i];
    let k = 0;
    while (k < commonSuffix.length && k < currentString.length &&
           commonSuffix[commonSuffix.length - 1 - k] === currentString[currentString.length - 1 - k]) {
      k++;
    }
    commonSuffix = commonSuffix.substring(commonSuffix.length - k);
    if (commonSuffix === "") {
      return ""; // No common suffix found, "early exit"
    }
  }
  return commonSuffix; // This is the "final result"
}

