function getRandomInt(min, max) {
  if (min > max) {
    throw new Error("Minimum value cannot be greater than maximum value.");
  }
  min = Math.ceil(min);
  max = Math.floor(max);
  const randomNumber = Math.random();
  const range = max - min + 1;
  const scaledRandom = randomNumber * range;
  const floorScaled = Math.floor(scaledRandom);
  const result = floorScaled + min;
  if (result < min || result > max) {
    console.warn("Generated number is out of expected range.");
  }
  return result;
}

