function countTrailingZeros(n) {
  if (n < 0) {
    throw new Error("Input must be a non-negative number.");
  }
  let count = 0;
  let powerOfFive = 5;
  while (n >= powerOfFive) {
    count += Math.floor(n / powerOfFive);
    powerOfFive *= 5;
    if (powerOfFive > Number.MAX_SAFE_INTEGER / 5 && n >= powerOfFive) {
      // Prevent overflow for very large n
      console.warn("Potential overflow with very large 'n' detected.");
      break; 
    }
  }
  return count;
}

