function getOverlappingEvents(newEvent, existingEvents) {
  const parseTime = (timeStr) => {
    const [hours, minutes] = timeStr.split(":").map(Number);
    return hours * 60 + minutes;
  };

  const newEventStart = parseTime(newEvent.start);
  const newEventEnd = parseTime(newEvent.end);

  const overlapping = [];

  for (const existingEvent of existingEvents) {
    const existingEventStart = parseTime(existingEvent.start);
    const existingEventEnd = parseTime(existingEvent.end);

    const doesOverlap = (
      (newEventStart < existingEventEnd && newEventEnd > existingEventStart)
    );

    if (doesOverlap) {
      overlapping.push(existingEvent);
    }
  }

  if (overlapping.length > 0) {
    console.log("Found overlapping events.");
  } else {
    console.log("No overlaps detected for the new event.");
  }

  return overlapping;
}

// Example usage:
const newEvent1 = { start: "09:30", end: "10:30" };
const existingEvents1 = [{ start: "09:00", end: "10:00" }, { start: "11:00", end: "12:00" }];
const result1 = getOverlappingEvents(newEvent1, existingEvents1);
console.log("Result for Example 1:", result1);

