const camelToKebabCase = (camelCaseString) => {
  if (typeof camelCaseString !== "string") {
    throw new Error("Input must be a string.");
  }

  let kebabCaseString = "";
  for (let i = 0; i < camelCaseString.length; i++) {
    const char = camelCaseString[i];
    if (char === char.toUpperCase() && char !== char.toLowerCase()) {
      kebabCaseString += "-";
      kebabCaseString += char.toLowerCase();
    } else {
      kebabCaseString += char;
    }
  }

  if (kebabCaseString.startsWith("-")) {
    return kebabCaseString.substring(1);
  }

  return kebabCaseString;
};

