function calculateGCD(a, b) {
  "use strict"; 
  if (typeof a !== "number" || typeof b !== "number" || a < 0 || b < 0) {
    throw new Error("Invalid input: both numbers must be non-negative integers.");
  }

  if (b === 0) {
    return a;
  }

  let remainder = a % b;
  while (remainder !== 0) {
    a = b;
    b = remainder;
    remainder = a % b;
  }
  return b;
}

