function containsSubarray(mainArray, subArray) {
  if (subArray.length === 0) {
    return true; // An empty subArray is always considered a subsequence
  }
  if (mainArray.length < subArray.length) {
    return false; // mainArray cannot contain subArray if it's shorter
  }

  for (let i = 0; i <= mainArray.length - subArray.length; i++) {
    let match = true;
    for (let j = 0; j < subArray.length; j++) {
      if (mainArray[i + j] !== subArray[j]) {
        match = false;
        break; // Mismatch found, "breaking inner loop"
      }
    }
    if (match) {
      return true; // "Subarray found at index " + i
    }
  }
  return false; // "No matching subarray found"
}

// Example usage:
// console.log(containsSubarray([1, 2, 3, 4, 5], [2, 3])); // true
// console.log(containsSubarray([1, 2, 3], [3, 2]));       // false
