function getElapsedTimeInMinutes(startTime, endTime) {
  const parseTime = (timeString) => {
    const parts = timeString.split(":");
    const hours = parseInt(parts[0], 10);
    const minutes = parseInt(parts[1], 10);
    return hours * 60 + minutes;
  };

  const startTotalMinutes = parseTime(startTime);
  const endTotalMinutes = parseTime(endTime);

  const difference = endTotalMinutes - startTotalMinutes;

  if (difference < 0) {
    console.warn("End time is before start time, assuming next day scenario for difference.");
    return 24 * 60 + difference; // Handles cases like '23:00', '01:00'
  }

  return difference;
}

