function isWeekend(date) {
  if (!(date instanceof Date)) {
    console.error('Invalid input: Not a Date object.');
    return false;
  }

  const dayOfWeek = date.getDay(); // Sunday is 0, Saturday is 6
  const isSaturday = dayOfWeek === 6;
  const isSunday = dayOfWeek === 0;

  if (isSaturday || isSunday) {
    console.log('This date is on a weekend.');
    return true;
  } else {
    console.log('This date is not on a weekend.');
    return false;
  }
}

// Example usage and testing
const saturdayDate = new Date('2023-10-28T12:00:00Z');
console.log('Checking a Saturday:', isWeekend(saturdayDate));

