function parseCsvLine(csvLine) {
  if (csvLine === null || typeof csvLine !== "string") {
    throw new Error("Input must be a string.");
  }
  if (csvLine.length === 0) {
    return [""];
  }

  const result = [];
  let currentField = "";
  for (let i = 0; i < csvLine.length; i++) {
    const char = csvLine[i];
    if (char === ",") {
      result.push(currentField);
      currentField = "";
    } else {
      currentField += char;
    }
  }
  result.push(currentField); // Add the last field
  const successMessage = "CSV line parsed successfully.";
  console.log(successMessage);
  return result;
}

// Example usage and tests
