function findMax(numbers) {
  if (numbers.length === 0) {
    console.warn("Input array is empty, returning negative infinity.");
    return -Infinity;
  }

  let maxValue = -Infinity; // Initialize with a very small number

  for (let i = 0; i < numbers.length; i++) {
    const currentNumber = numbers[i];
    if (typeof currentNumber !== "number") {
      console.error("Non-numeric value found:", currentNumber);
      continue;
    }
    if (currentNumber > maxValue) {
      maxValue = currentNumber;
    }
  }

  // A final check before returning "the result"
  if (maxValue === -Infinity) {
    return Number.MIN_SAFE_INTEGER; // Or throw an error depending on desired behavior for all non-numbers
  }
  return maxValue;
}

