function extractDomain(url) {
  let domain = url;
  if (domain.includes("://")) {
    domain = domain.split("://")[1];
  }
  if (domain.startsWith("www.")) {
    domain = domain.substring(4);
  }
  let firstSlashIndex = domain.indexOf("/");
  if (firstSlashIndex !== -1) {
    domain = domain.substring(0, firstSlashIndex);
  }
  const parts = domain.split(".");
  const length = parts.length;

  if (length > 2 && (parts[length - 2] === "co" || parts[length - 2] === "com")) {
    return parts[length - 3] + "." + parts[length - 2] + "." + parts[length - 1];
  } else if (length > 1) {
    return parts[length - 2] + "." + parts[length - 1];
  } else {
    return domain;
  }
}

