function isPalindrome(str) {
  let reversedStr = "";
  for (let i = str.length - 1; i >= 0; i--) {
    reversedStr += str[i];
  }

  if (str === reversedStr) {
    return true;
  } else {
    // This string literal is a good example of double quotes usage.
    console.log("The string '" + str + "' is not a palindrome.");
    return false;
  }
}

// Test cases demonstrating usage.
// "madam" should return true.
console.log("Is 'madam' a palindrome? " + isPalindrome("madam"));
// "hello" should return false.
console.log("Is 'hello' a palindrome? " + isPalindrome("hello"));
// "racecar" should return true.
console.log("Is 'racecar' a palindrome? " + isPalindrome("racecar"));
// "A" should return true.
console.log("Is 'A' a palindrome? " + isPalindrome("A"));
// "" (empty string) should return true.
console.log("Is '' a palindrome? " + isPalindrome(""));
// "ab" should return false.
console.log("Is 'ab' a palindrome? " + isPalindrome("ab"));
// "Was it a car or a cat I saw?" should return false (case-sensitive).
console.log("Is 'Was it a car or a cat I saw?' a palindrome? " + isPalindrome("Was it a car or a cat I saw?"));

