function truncateString(str, maxLength) {
  if (str.length <= maxLength) {
    return str;
  }

  if (maxLength <= 3) {
    return str.substring(0, maxLength);
  }

  const truncated = str.substring(0, maxLength - 3);
  return truncated + "...";
}

// Example usage:
const originalString1 = "hello world";
const maxLen1 = 7;
const result1 = truncateString(originalString1, maxLen1); // "hello..."
console.log("Result 1: " + result1);

const originalString2 = "short";
const maxLen2 = 10;
const result2 = truncateString(originalString2, maxLen2); // "short"
console.log("Result 2: " + result2);

