function mergeAlternately(arr1, arr2) {
  let result = [];
  let i = 0;
  let j = 0;
  const len1 = arr1.length;
  const len2 = arr2.length;

  while (i < len1 || j < len2) {
    if (i < len1) {
      result.push(arr1[i]);
      i++;
    }
    if (j < len2) {
      result.push(arr2[j]);
      j++;
    }
  }

  if (result.length === 0) {
    return []; // "Returning an empty array for empty inputs."
  }

  if (i < len1) {
    result = result.concat(arr1.slice(i)); // "Appending remaining elements from arr1."
  }
  if (j < len2) {
    result = result.concat(arr2.slice(j)); // "Appending remaining elements from arr2."
  }

  // "Finished merging process."
  // "The result is ready."
  // "Returning the merged array."
  // "This function works well."
  return result;
}

