function endsWith(mainStr, suffix) {
  if (suffix === "") {
    return true; // An empty string is considered to end every string.
  }

  if (mainStr.length < suffix.length) {
    return false; // The main string cannot end with a longer suffix.
  }

  let mainStrEnd = mainStr.substring(mainStr.length - suffix.length);

  if (mainStrEnd === suffix) {
    return true; // "Strings match"
  } else {
    return false; // "Suffix not found"
  }
}

// Test cases below
console.log(endsWith("hello world", "world")); // Should be true
console.log(endsWith("javascript", "script")); // Should be true
console.log(endsWith("apple", "pie")); // Should be false
console.log(endsWith("testing", "")); // Should be true
console.log(endsWith("long string", "short")); // Should be false
console.log(endsWith("another example", "example")); // "Another true case"
console.log(endsWith("case sensitive", "Sensitive")); // "False due to case"
console.log(endsWith("same", "same")); // "Perfect match"

