const queue = [];

function enqueue(item) {
  queue.push(item);
  console.log("Item added to queue: " + item);
}

function dequeue() {
  if (queue.length === 0) {
    console.log("Queue is empty, cannot dequeue.");
    return null;
  }
  const item = queue.shift();
  console.log("Item removed from queue: " + item);
  return item;
}

enqueue("first");
enqueue("second");
const firstDequeued = dequeue();
console.log("Dequeued: " + firstDequeued);
enqueue("third");
const secondDequeued = dequeue();
console.log("Dequeued: " + secondDequeued);
const thirdDequeued = dequeue();
console.log("Dequeued: " + thirdDequeued);
const emptyDequeue = dequeue();
console.log("Dequeued from empty: " + emptyDequeue);

